/**
 * OpenAI Client — minimal chat-completions wrapper.
 *
 * Used by PromptArmorBaseline (and any future OpenAI-backed feature) for
 * single-call detector-style requests: system prompt + one user message,
 * no tools, no streaming, deterministic temperature. Mirrors the
 * shape of bedrock-client.ts so callers can swap backends with the
 * same surface.
 *
 * Uses the global fetch (Node 22+) to avoid adding the openai SDK as
 * a runtime dependency. The chat-completions API surface is stable
 * enough for this.
 *
 * Caller responsibilities:
 *   - Set OPENAI_API_KEY in env. We do not read this at module load
 *     so the absence is a per-call failure rather than a startup crash.
 *   - Pick the model. We don't map friendly aliases here (executor-
 *     openai.ts has a MODEL_MAP for that — caller-side concern).
 */

interface OpenAIChatResponse {
  choices: Array<{
    message: { content: string | null };
    finish_reason: string;
  }>;
  usage: {
    prompt_tokens: number;
    completion_tokens: number;
    total_tokens: number;
  };
}

export interface OpenAIChatResult {
  content: string;
  durationMs: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  finishReason: string;
}

export async function openaiChat(
  systemPrompt: string,
  userMessage: string,
  modelId: string,
  opts: {
    /** Defaults to 0 for deterministic detector-style use. */
    temperature?: number;
    /** Cap on output tokens. */
    maxTokens?: number;
    /** Per-call abort timeout in ms; default 60s. */
    timeoutMs?: number;
  } = {},
): Promise<OpenAIChatResult> {
  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey) {
    throw new Error("OPENAI_API_KEY not set");
  }

  const body = {
    model: modelId,
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userMessage },
    ],
    temperature: opts.temperature ?? 0,
    max_tokens: opts.maxTokens ?? 256,
  };

  const start = Date.now();
  const maxAttempts = 3;
  let lastErr: Error | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(opts.timeoutMs ?? 60_000),
      });

      if (!res.ok) {
        const text = await res.text().catch(() => "");
        if ((res.status === 429 || res.status >= 500) && attempt < maxAttempts) {
          const backoff = 1000 * Math.pow(2, attempt - 1);
          console.warn(
            `  [openai ${res.status}] attempt ${attempt}/${maxAttempts}; sleeping ${backoff}ms`,
          );
          await new Promise((r) => setTimeout(r, backoff));
          continue;
        }
        throw new Error(`OpenAI HTTP ${res.status}: ${text.substring(0, 500)}`);
      }

      const json = (await res.json()) as OpenAIChatResponse;
      const choice = json.choices?.[0];
      const content = choice?.message?.content ?? "";
      const usage = json.usage ?? { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
      return {
        content,
        durationMs: Date.now() - start,
        inputTokens: usage.prompt_tokens,
        outputTokens: usage.completion_tokens,
        totalTokens: usage.total_tokens,
        finishReason: choice?.finish_reason ?? "unknown",
      };
    } catch (err) {
      lastErr = err instanceof Error ? err : new Error(String(err));
      if (attempt < maxAttempts) {
        const backoff = 1000 * Math.pow(2, attempt - 1);
        console.warn(
          `  [openai fetch] attempt ${attempt}/${maxAttempts}: ${lastErr.message}; sleeping ${backoff}ms`,
        );
        await new Promise((r) => setTimeout(r, backoff));
        continue;
      }
    }
  }
  throw lastErr ?? new Error("OpenAI call failed with no captured error");
}

/**
 * Clerk authentication for the dashboard container.
 *
 * Verifies Clerk session JWTs in the `Authorization: Bearer <token>` header
 * via `@clerk/backend`'s framework-neutral `verifyToken`. Used by every
 * `/api/*` route handler in `server-dashboard.ts` (except `/health` and
 * `/api/health`, which the platform's ALB and the dashboard's own browser
 * hits unauthenticated for status display).
 *
 * Two roles:
 *  - admin    — emails listed in ADMIN_EMAILS. Can change trust mode, see
 *               every user's API keys, sessions, and console logs.
 *  - user     — any other authenticated identity. Can only see their own
 *               sessions (via SessionStore.ownerSub), only their own API
 *               keys, and cannot toggle trust mode.
 *
 * The admin allow-list is hard-coded on purpose. There is no public
 * "promote to admin" endpoint and no env-var override — adding an admin
 * means a code change and a redeploy. That's the right shape for a
 * privilege you can't otherwise audit.
 *
 * Auth wiring:
 *   - publishable key (browser): CLERK_PUBLISHABLE_KEY OR
 *     NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY (whichever is set)
 *   - secret key (this module):  CLERK_SECRET_KEY
 *
 * If CLERK_SECRET_KEY is unset on a non-local deploy, every /api/* call
 * returns 503 "auth not configured" — fail-closed rather than expose
 * dashboard data.
 */

import { type IncomingMessage, type ServerResponse } from "node:http";
import { createPublicKey } from "node:crypto";
import { verifyToken } from "@clerk/backend";
import { json } from "./server-core.js";

const CLERK_SECRET_KEY = process.env.CLERK_SECRET_KEY ?? "";
export const CLERK_PUBLISHABLE_KEY =
  process.env.CLERK_PUBLISHABLE_KEY ??
  process.env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY ??
  "";

// Static JWKS public key. When set, verifyToken uses it directly and
// makes ZERO outbound network calls — sidesteps the egress allowlist
// problem entirely. The cost is that key rotation requires a redeploy
// (Clerk rotates ~yearly for instances, much rarer in practice).
//
// Two acceptable formats:
//   - PEM string: starts with "-----BEGIN PUBLIC KEY-----"
//   - JWK string: a single JSON object {"kty":"RSA","n":"…","e":"…",…}
// Either is fed to verifyToken({ jwtKey: <PEM> }) — verifyToken accepts
// PEM directly, and we convert JWK→PEM in code so operators can paste
// either shape into the env var.
//
// If unset, the SDK falls back to network JWKS discovery (the path that
// has been timing out from this Fargate task).
const CLERK_JWT_PUBLIC_KEY_RAW = process.env.CLERK_JWT_PUBLIC_KEY ?? "";

const CLERK_JWT_PUBLIC_KEY_PEM: string | null = (() => {
  const raw = CLERK_JWT_PUBLIC_KEY_RAW.trim();
  if (!raw) return null;
  if (raw.startsWith("-----BEGIN")) return raw;
  // Treat as JWK — try to parse and convert to PEM via Node's crypto.
  try {
    const jwk = JSON.parse(raw);
    const key = createPublicKey({ key: jwk, format: "jwk" });
    return key.export({ type: "spki", format: "pem" }) as string;
  } catch (err) {
    console.warn(
      `[clerk] CLERK_JWT_PUBLIC_KEY is set but not a valid PEM or JWK: ${
        err instanceof Error ? err.message : err
      }`,
    );
    return null;
  }
})();

/** Hard-coded admin allow-list. Changing this requires a code commit. */
const ADMIN_EMAILS = new Set<string>([
  "adrian.asher@checkout.com",
  "adrianasher30@gmail.com",
]);

export interface ClerkPrincipal {
  /** Clerk userId (sub claim) — stable across sessions; used as ownerSub
   *  when minting API keys. */
  userId: string;
  /** Primary verified email. Empty if Clerk didn't surface one. */
  email: string;
  /** Set true iff `email` is in ADMIN_EMAILS. */
  isAdmin: boolean;
  /** Raw verified claims. For audit / future scope checks. */
  claims: Record<string, unknown>;
}

export function isAdminEmail(email: string | null | undefined): boolean {
  if (!email) return false;
  return ADMIN_EMAILS.has(email.toLowerCase());
}

function extractBearer(req: IncomingMessage): string | null {
  const h = req.headers.authorization;
  if (typeof h !== "string") return null;
  const m = /^\s*Bearer\s+(\S+)\s*$/i.exec(h);
  return m ? m[1] : null;
}

function extractEmail(claims: Record<string, unknown>): string {
  // Clerk session JWTs contain a "primary_email_address_id" + a custom
  // template can include "email". We accept either; preferring "email"
  // because that's what we ask Clerk to put in the template.
  const direct = claims["email"];
  if (typeof direct === "string") return direct.toLowerCase();
  const eml = claims["primary_email"];
  if (typeof eml === "string") return eml.toLowerCase();
  // Fall back to userId so admin checks always fail gracefully when the
  // template is misconfigured (no admin promotion ever via a missing claim).
  return "";
}

/**
 * Verify the Clerk token on `req` without writing to `res`. Used by
 * /api/whoami where we want to surface "no auth yet" rather than 401.
 * Returns the principal on success, or a structured failure reason on
 * failure — the dashboard surfaces the reason in the sign-in overlay
 * so a misconfigured Clerk origin doesn't look like a generic "401".
 */
export type ClerkVerifyResult =
  | { ok: true; principal: ClerkPrincipal }
  | { ok: false; reason: "no-secret" | "no-token" | "no-sub" | "verify-failed"; error?: string };

export async function tryVerifyClerk(req: IncomingMessage): Promise<ClerkVerifyResult> {
  if (!CLERK_SECRET_KEY) return { ok: false, reason: "no-secret" };
  const token = extractBearer(req);
  if (!token) return { ok: false, reason: "no-token" };
  try {
    // Prefer the static public key when it's been provisioned — that
    // path is offline and never goes near the egress allowlist. Falls
    // back to the network JWKS discovery flow when the env var is unset.
    const verifyOpts: any = CLERK_JWT_PUBLIC_KEY_PEM
      ? { jwtKey: CLERK_JWT_PUBLIC_KEY_PEM }
      : { secretKey: CLERK_SECRET_KEY };
    const claims = await verifyToken(token, verifyOpts);
    const userId = (claims as any).sub;
    if (typeof userId !== "string" || !userId) {
      return { ok: false, reason: "no-sub" };
    }
    const email = extractEmail(claims as Record<string, unknown>);
    return {
      ok: true,
      principal: {
        userId,
        email,
        isAdmin: isAdminEmail(email),
        claims: claims as Record<string, unknown>,
      },
    };
  } catch (err) {
    // Surface the real cause. undici's "fetch failed" hides the actual
    // network error in err.cause (e.g. ENOTFOUND, ECONNREFUSED, TLS
    // failures, 4xx from a proxy). Without unwrapping it, an operator
    // sees "fetch failed" and can't tell DNS from egress firewall.
    const top = err instanceof Error ? err.message : String(err);
    const cause = (err as any)?.cause;
    const causeMsg =
      cause instanceof Error
        ? `${cause.name}: ${cause.message}` +
          ((cause as any).code ? ` (code=${(cause as any).code})` : "")
        : cause
          ? String(cause)
          : "";
    const error = causeMsg ? `${top} — cause: ${causeMsg}` : top;
    console.warn(`[clerk] verifyToken failed: ${error}`);
    return { ok: false, reason: "verify-failed", error };
  }
}

/**
 * Explicit egress probe. The dashboard's settings modal pings this so
 * an operator can tell whether Clerk's APIs are reachable from the
 * container without fishing through CloudWatch logs.
 *
 * Returns one entry per host the runtime actually contacts:
 *  - frontend-api: <slug>.clerk.accounts.dev — derived from the
 *    publishable key, used by the browser SDK + by some discovery
 *    paths in @clerk/backend.
 *  - backend-api: api.clerk.com — used by @clerk/backend.verifyToken
 *    to fetch the JWKS for signature verification. THIS is the host
 *    the firewall most often forgets.
 *
 * The result is an array so a partial allowlist (one host reachable,
 * one not) is visible at a glance.
 */
export async function probeClerkConnectivity(): Promise<{
  hosts: Array<{
    label: string;
    host: string;
    url: string;
    ok: boolean;
    status?: number;
    error?: string;
  }>;
}> {
  const hosts: Array<{
    label: string;
    host: string;
    url: string;
    ok: boolean;
    status?: number;
    error?: string;
  }> = [];

  // 1. Frontend API — derived from publishable key.
  const partsB64 = CLERK_PUBLISHABLE_KEY ? CLERK_PUBLISHABLE_KEY.split("_")[2] ?? "" : "";
  let frontendHost = "";
  if (partsB64) {
    try {
      frontendHost = Buffer.from(partsB64, "base64").toString("utf8").replace(/\$$/, "");
    } catch {
      /* leave empty */
    }
  }
  if (frontendHost) {
    hosts.push(
      await probeOne(
        "frontend-api",
        frontendHost,
        `https://${frontendHost}/.well-known/jwks.json`,
      ),
    );
  } else {
    hosts.push({
      label: "frontend-api",
      host: "(unknown)",
      url: "",
      ok: false,
      error: "Could not derive frontend-api host (publishable key missing or malformed)",
    });
  }

  // 2. Backend API — what @clerk/backend.verifyToken actually fetches
  // when it needs the JWKS. Always api.clerk.com regardless of dev/prod
  // for keys minted from the standard Clerk hosting plane.
  hosts.push(await probeOne("backend-api", "api.clerk.com", "https://api.clerk.com/v1/jwks"));

  return { hosts };
}

async function probeOne(
  label: string,
  host: string,
  url: string,
): Promise<{
  label: string;
  host: string;
  url: string;
  ok: boolean;
  status?: number;
  error?: string;
}> {
  try {
    const r = await fetch(url, { method: "GET", signal: AbortSignal.timeout(5_000) });
    return { label, host, url, ok: r.ok, status: r.status };
  } catch (err) {
    const top = err instanceof Error ? err.message : String(err);
    const cause = (err as any)?.cause;
    const causeMsg =
      cause instanceof Error
        ? `${cause.name}: ${cause.message}` +
          ((cause as any).code ? ` (code=${(cause as any).code})` : "")
        : cause
          ?

/**
 * Bedrock Client
 *
 * Calls the judge LLM (Sonnet/Nemotron/etc.) via Bedrock's Converse API
 * and embedding models via InvokeModel. Uses the AWS SDK directly so the
 * call is async (non-blocking) and the credential chain is the standard
 * Node SDK chain (env vars, shared config, IRSA / IMDSv2 on Fargate).
 *
 * History: this used to shell out to `aws bedrock-runtime ...` via
 * `execSync` with temp-file payloads. That was 1-concurrency (the event
 * loop blocked for ~1.5s per judge call) and added a 150–300 ms
 * process-spawn cost on every invocation. Replacing with the SDK fixes
 * both. See also task #12 / commit history.
 */

import {
  BedrockRuntimeClient,
  ConverseCommand,
  InvokeModelCommand,
} from "@aws-sdk/client-bedrock-runtime";

const REGION = process.env.BEDROCK_REGION ?? process.env.AWS_REGION ?? "eu-central-1";
const MODEL_ID = process.env.BEDROCK_JUDGE_MODEL ?? "nvidia.nemotron-super-3-120b";

type EffortLevel = "low" | "medium" | "high" | "xhigh" | "max" | "none";

export interface BedrockImageBlock {
  /** Base64-encoded image data */
  data: string;
  /** MIME type, e.g. "image/png" */
  mediaType: string;
}

// Module-level client per region. Most calls use the same region, so this
// is effectively a singleton with a fallback for cross-region embeddings
// (e.g. judge in eu-west-2, embeddings in eu-west-1).
const clients = new Map<string, BedrockRuntimeClient>();
function clientFor(region: string): BedrockRuntimeClient {
  let c = clients.get(region);
  if (!c) {
    c = new BedrockRuntimeClient({ region });
    clients.set(region, c);
  }
  return c;
}

export async function bedrockChat(
  systemPrompt: string,
  userMessage: string,
  modelId = MODEL_ID,
  effort?: EffortLevel,
  images?: BedrockImageBlock[]
): Promise<{
  content: string;
  thinking: string;
  durationMs: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  cacheReadInputTokens?: number;
  cacheWriteInputTokens?: number;
  hasThinkingBlock: boolean;
  estimatedThinkingTokens: number;
}> {
  const start = Date.now();
  if (effort === "none") effort = undefined;

  // Build user content (text + optional images).
  const userContent: any[] = [{ text: userMessage }];
  if (images?.length) {
    for (const img of images) {
      const format = img.mediaType.replace("image/", "");
      // SDK requires `bytes` to be a Uint8Array, not a base64 string.
      const bytes = Buffer.from(img.data, "base64");
      userContent.push({ image: { format, source: { bytes } } });
    }
  }

  const budgetMap: Record<string, number> = { low: 1024, medium: 5000, high: 16000, max: 60000 };
  const budgetTokens = budgetMap[effort!] ?? 5000;
  const isOpus47 = modelId.includes("opus-4-7") || modelId.includes("opus-4-8");
  const inferenceConfig: Record<string, unknown> = {
    maxTokens: effort ? (isOpus47 ? 16384 : Math.min(budgetTokens + 4096, 64000)) : 512,
  };
  if (!isOpus47) inferenceConfig.temperature = effort ? 1 : 0.1;

  // SDK types `additionalModelRequestFields` as `DocumentType` which doesn't
  // accept conditional shapes cleanly — cast to any. The wire format is
  // model-runtime-defined (Anthropic vs Nova etc.), so the SDK leaves it open.
  const additionalModelRequestFields: any = effort
    ? (isOpus47
        ? { thinking: { type: "adaptive" }, output_config: { effort } }
        : { thinking: { type: "enabled", budget_tokens: budgetTokens } })
    : undefined;

  // Prompt caching: mark the system prompt as a cache point so the
  // 6500-token B7.1 hardened prompt is billed at 10% of the input rate
  // for the next 5 minutes (cache TTL). The cache key is "everything
  // before this marker"; the per-call user message after it is billed
  // normally.
  //
  // Only effective when the cached portion is >= ~1024 tokens (Bedrock
  // minimum). The standard SYSTEM_PROMPT may fall under that threshold
  // and Bedrock will silently skip caching — that's fine, the marker
  // costs nothing on a no-op.
  //
  // We do NOT mark a cache point inside the user content because that
  // changes per call (tool input, file context, agent reasoning) — caching
  // it would invalidate every time. The system prompt is the static
  // 90%+ of every judge request.
  const systemBlocks: any[] = [
    { text: systemPrompt },
    { cachePoint: { type: "default" } },
  ];

  const command = new ConverseCommand({
    modelId,
    system: systemBlocks,
    messages: [{ role: "user", content: userContent }],
    inferenceConfig,
    ...(additionalModelRequestFields ? { additionalModelRequestFields } : {}),
  });

  // Hard timeout on the Bedrock call — a stuck request previously
  // hung the event loop indefinitely (CloudWatch outage on
  // 2026-05-10T03:17 to 07:32 UTC: hook went silent after a single
  // /screen call never returned, ALB health-check took 2h 23m to
  // notice). 120s is generous — opus thinking-mode runs can take
  // 30-60s. Anything longer is a hung connection, not a slow model.
  // Override via BEDROCK_REQUEST_TIMEOUT_MS for thinking-mode runs
  // that legitimately need more headroom.
  const timeoutMs = parseInt(process.env.BEDROCK_REQUEST_TIMEOUT_MS ?? "120000", 10);
  const response = await clientFor(REGION).send(command, {
    abortSignal: AbortSignal.timeout(timeoutMs),
  });

  const blocks = (response.output?.message?.content ?? []) as any[];
  const content = blocks
    .filter((c) => c.text !== undefined)
    .map((c) => c.text as string)
    .join("");
  const thinking = blocks
    .filter((c) => c.reasoningContent !== undefined)
    .map((c) => {
      const rc = c.reasoningContent;
      const rt = rc.reasoningText;
      return (rt?.text ?? rc.text ?? "") as string;
    })
    .join("");

  const usage: any = response.usage ?? {};
  const inputTokens = usage.inputTokens ?? 0;
  const outputTokens = usage.outputTokens ?? 0;
  const hasThinkingBlock = blocks.some((c) => c.reasoningContent !== undefined);
  return {
    content,
    thinking,
    durationMs: Date.now() - start,
    inputTokens,
    outputTokens,
    totalTokens: usage.totalTokens ?? (inputTokens + outputTokens),
    cacheReadInputTokens: usage.cacheReadInputTokens ?? undefined,
    cacheWriteInputTokens: usage.cacheWriteInputTokens ?? undefined,
    hasThinkingBlock,
    estimatedThinkingTokens: thinking ? Math.ceil(thinking.length / 4) : 0,
  };
}

// ============================================================================
// Embedding API
// ============================================================================

/**
 * Embed a batch of texts using a Bedrock embedding model.
 * Dispatches to the correct request/response format per model family.
 */
export async function bedrockEmbed(
  texts: string[],
  modelId: string,
  region = REGION
): Promise<number[][]> {
  // Strip cross-region inference profile prefixes (eu., us., global.) before dispatch
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");

  if (bare.startsWith("cohere.embed")) {
    return cohereEmbed(texts, modelId, region);
  }
  if (bare.startsWith("amazon.titan-embed")) {
    return Promise.all(texts.map((t) => titanEmbed(t, modelId, region)));
  }
  if (bare.startsWith("twelvelabs.")) {
    return Promise.all(texts.map((t) => marengoEmbed(t, modelId, region)));
  }
  throw new Error(`Unknown Bedrock embedding model family: ${modelId}`);
}

async function invokeModel(modelId: string, body: object, region: string): Promise<object> {
  const command = new InvokeModelCommand({
    modelId,
    body: new TextEncoder().encode(JSON.stringify(body)),
    contentType: "application/json",
    accept: "application/json",
  });
  const response = await clientFor(region).send(command);
  // SDK returns response.body as Uint8Array.
  const bytes = response.body as Uint8Array;
  return JSON.parse(new TextDecoder().decode(bytes));
}

async function cohereEmbed(texts: string[], modelId: string, region: string): Promise<number[][]> {
  const resp = (await invokeModel(modelId, { texts, input_type: "search_query" }, region)) as Record<string, unknown>;
  // v3: { embeddings: number[][] }
  // v4: { embeddings: { float: number[][] } }
  const emb = resp.embeddings as number[][] | { float: number[][] };
  return Array.isArray(emb) ? emb : emb.float;
}

async function titanEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  const resp = (await invokeModel(modelId, { inputText: text }, region)) as { embedding: number[] };
  return resp.embedding;
}

async function marengoEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  // Marengo 3.0: { inputType: "text", text: { text: "..." } }
  // Marengo 2.7: { inputType: "text", inputText: "..." }
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");
  const body = bare.includes("marengo-embed-2-7")
    ? { inputType: "text", inputText: text }
    : { inputType: "text", text: { inputText: text } };

  const resp = (await invokeModel(modelId, body, region)) as Record<string, unknown>;
  if (Array.isArray(resp.embedding)) return resp.embedding as number[];
  const data = resp.data as { embedding: number[] }[] | undefined;
  if (data?.[0]?.embedding) return data[0].embedding;
  throw new Error(`Unexpected Marengo response shape: ${JSON.stringify(resp).substring(0, 200)}`);
}

export async function checkBedrock(modelId = MODEL_ID): Promise<boolean> {
  // Test with a real Converse call — avoids needing metadata API permissions
  // (bedrock:ListInferenceProfiles, bedrock:GetFoundationModel).
  try {
    const command = new ConverseCommand({
      modelId,
      messages: [{ role: "user", content: [{ text: "ok" }] }],
      inferenceConfig: { maxTokens: 1 },
    });
    // Short timeout on the preflight: 30s is plenty for a 1-token
    // sanity call. Don't let preflight hang container startup.
    await clientFor(REGION).send(command, { abortSignal: AbortSignal.timeout(30_000) });
    return true;
  } catch {
    return false;
  }
}

/**
 * Shared module-level state for the hook-side route handlers.
 *
 * When the handlers lived in `server-hook.ts`, these were just file-
 * scope `const`s. After the per-handler split each handler file imports
 * the bits it needs from here — keeps the per-handler imports honest
 * about what they depend on while preserving the single-instance
 * semantics (one IntentClassifier, one mode-override Map per process).
 */

import { readFileSync } from "node:fs";
import { CONFIG, type TrustMode } from "../server-core.js";
import { IntentClassifier } from "../intent-classifier.js";

/** History-active model rollout — top-level flag gating the new
 *  intent-classifier behaviour. Layered with INTENT_CLASSIFIER_LLM_ENABLED
 *  so we can stage the rollout:
 *
 *   legacy (default):
 *     - Schema layer always runs (Steps 1-2 are behaviour-equivalent;
 *       existing call sites use getActiveIntents/setActiveIntents and
 *       see exactly the legacy stack).
 *     - The new sub-task / replacement / revisit kinds DO NOT fire.
 *     - Judge sees the legacy plain numbered list (no [annotation]
 *       suffixes).
 *     - The async LLM classifier never starts.
 *
 *   history-active:
 *     - The Step-3 embedding classifier produces the new kinds.
 *     - Judge prompt renders parent/child + replacement annotations.
 *     - LLM classifier may run if INTENT_CLASSIFIER_LLM_ENABLED is
 *       also true.
 *
 * Step-6 staged rollout: enable history-active first (cost-neutral —
 * just smarter classification + richer judge prompts). Once telemetry
 * confirms the classification rates look sensible, flip
 * INTENT_CLASSIFIER_LLM_ENABLED to add the LLM safety net. */
export const INTENT_HISTORY_MODE: "legacy" | "history-active" =
  process.env.INTENT_HISTORY_MODE === "history-active" ? "history-active" : "legacy";

export const INTENT_CLASSIFIER_LLM_ENABLED =
  process.env.INTENT_CLASSIFIER_LLM_ENABLED === "true"
  && INTENT_HISTORY_MODE === "history-active";

export const intentClassifier = new IntentClassifier(
  (process.env.INTENT_CLASSIFIER_BACKEND as "bedrock" | "ollama" | undefined) ?? "bedrock",
  process.env.INTENT_CLASSIFIER_MODEL ?? "eu.anthropic.claude-sonnet-4-6",
);

/** How long /evaluate waits for an in-flight classifier verdict
 *  before falling back to the existing active state. Cap chosen to
 *  stay below typical agent-response latency so it's hidden in
 *  normal flow. */
export const CLASSIFIER_EVALUATE_WAIT_MS = 750;

/** Build version, surfaced in every permissionDecisionReason so users
 *  can tell which deployment produced an error. Read once at module
 *  load — package.json is baked into the image. */
export const PKG_VERSION: string = (() => {
  try {
    return JSON.parse(
      readFileSync(new URL("../../package.json", import.meta.url), "utf8")
    ).version as string;
  } catch {
    return "unknown";
  }
})();

export const DREDD_TAG = `Judge AI Dredd [v${PKG_VERSION}]`;

/** Per-session trust-mode override. Set via POST /api/session-mode from
 *  the dashboard. Beats body.mode and CONFIG.mode for that one session —
 *  used to rescue stuck sessions where the LLM stack classifier has
 *  locked onto a stale goal and every command trips drift-deny. In-
 *  memory; cleared on container restart. ALB stickiness keeps the
 *  session pinned to one task so the override stays effective for the
 *  session's lifetime. */
export const sessionModeOverride = new Map<string, TrustMode>();

export function effectiveMode(session_id: string, bodyMode: unknown): TrustMode {
  const override = sessionModeOverride.get(session_id);
  if (override) return override;
  return ((bodyMode as TrustMode | undefined) ?? CONFIG.mode);
}

/** Per-session intent-history-model override. Same shape as
 *  sessionModeOverride but for the history-active rollout — lets a
 *  sandbox A/B-test history-active on one session while production
 *  stays on legacy. Set via POST /api/session-intent-mode. */
export const sessionIntentModeOverride = new Map<string, "legacy" | "history-active">();

export function effectiveIntentHistoryMode(session_id: string): boolean {
  const override = sessionIntentModeOverride.get(session_id);
  if (override) return override === "history-active";
  return INTENT_HISTORY_MODE === "history-active";
}

/**
 * Ollama Client
 *
 * Lightweight HTTP client for Ollama's local API.
 * Provides embedding generation and chat completion
 * without any external dependencies.
 */

const OLLAMA_BASE = process.env.OLLAMA_HOST ?? "http://localhost:11434";

export interface EmbeddingResponse {
  embeddings: number[][];
}

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
  /** Base64-encoded images (Ollama vision models only) */
  images?: string[];
}

export interface ChatResponse {
  message: {
    role: string;
    content: string;
  };
  total_duration?: number;
  eval_count?: number;
}

/**
 * Generate embeddings for one or more texts.
 */
export async function embed(
  texts: string | string[],
  model = "nomic-embed-text"
): Promise<number[][]> {
  const input = Array.isArray(texts) ? texts : [texts];

  const res = await fetch(`${OLLAMA_BASE}/api/embed`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, input }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Ollama embed failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as EmbeddingResponse;
  return data.embeddings;
}

/**
 * Chat completion with a local model. Streaming disabled for simplicity.
 */
export async function chat(
  messages: ChatMessage[],
  model = "llama3.2"
): Promise<{ content: string; durationMs: number }> {
  const start = Date.now();

  const res = await fetch(`${OLLAMA_BASE}/api/chat`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, messages, stream: false }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Ollama chat failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as ChatResponse;
  return {
    content: data.message.content,
    durationMs: Date.now() - start,
  };
}

/**
 * Route an embed call to Bedrock or Ollama based on the model name.
 * Bedrock model IDs start with a known provider prefix (with or without a
 * region qualifier like eu./us./global.). Ollama model names never do.
 */
const BEDROCK_PREFIXES = /^(?:eu\.|us\.|global\.|amazon\.|cohere\.|twelvelabs\.|anthropic\.|meta\.|mistral\.|nvidia\.)/;

export function isBedrockModel(model: string): boolean {
  return BEDROCK_PREFIXES.test(model);
}

export async function embedAny(
  texts: string | string[],
  model: string
): Promise<number[][]> {
  if (isBedrockModel(model)) {
    const { bedrockEmbed } = await import("./bedrock-client.js");
    const arr = Array.isArray(texts) ? texts : [texts];
    return bedrockEmbed(arr, model);
  }
  return embed(texts, model);
}

/**
 * Cosine similarity between two vectors.
 */
export function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) {
    throw new Error(`Vector dimension mismatch: ${a.length} vs ${b.length}`);
  }
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}

/**
 * Check if Ollama is reachable and the required models are available.
 */
export async function checkOllama(
  embeddingModel: string,
  chatModel?: string
): Promise<{ ok: boolean; missing: string[] }> {
  const required = chatModel ? [embeddingModel, chatModel] : [embeddingModel];
  try {
    const res = await fetch(`${OLLAMA_BASE}/api/tags`);
    if (!res.ok) return { ok: false, missing: required };

    const data = (await res.json()) as { models: { name: string }[] };
    const available = new Set(data.models.map((m) => m.name.split(":")[0]));

    const missing: string[] = [];
    for (const m of required) {
      if (!available.has(m.split(":")[0])) missing.push(m);
    }

    return { ok: missing.length === 0, missing };
  } catch {
    return { ok: false, missing: required };
  }
}

